from __future__ import annotations

import base64
from pathlib import Path
from typing import Any

ICON_ICO_B64 = ""
ICON_PNG_B64 = ""


def apply_window_icon(root: Any) -> None:
    try:
        import tkinter as tk

        image = tk.PhotoImage(data=ICON_PNG_B64)
        root.iconphoto(True, image)
        root._dmtorrent2part_icon = image
    except Exception:
        pass


def write_ico(path: str | Path) -> Path:
    target = Path(path)
    target.write_bytes(base64.b64decode(ICON_ICO_B64))
    return target
